"use client"

import React from "react"
import * as AccordionPrimitive from "@radix-ui/react-accordion"
import { type VariantProps, cva } from "class-variance-authority"
import { ChevronDownIcon, Plus } from "lucide-react"
import { cn as classNames } from "@/lib/utils"

// Defining the types for the accordion
export type AccordionContextType = {
	size?: VariantProps<typeof accordionVariants>["size"]
	variant?: VariantProps<typeof accordionVariants>["variant"]
	indicator?: VariantProps<typeof accordionTriggerVariants>["indicator"]
}

export type AccordionProps = React.ComponentProps<typeof AccordionPrimitive.Root> &
	VariantProps<typeof accordionVariants> & {
		indicator?: VariantProps<typeof accordionTriggerVariants>["indicator"]
	}

export type AccordionItemProps = React.ComponentProps<typeof AccordionPrimitive.Item>

export type AccordionTriggerProps = React.ComponentProps<typeof AccordionPrimitive.Trigger>

export type AccordionContentProps = React.ComponentProps<typeof AccordionPrimitive.Content>

const AccordionContext = React.createContext<AccordionContextType | null>(null)

// Defining the different variants for the accordion
const accordionVariants = cva("w-full", {
	variants: {
		size: {
			sm: "text-sm/6",
			lg: "text-base/7",
		},
		variant: {
			box: "",
			table: "border-stroke rounded-xl border",
			open: "",
		},
	},
	defaultVariants: {
		size: "sm",
		variant: "box",
	},
})

const accordionItemVariants = cva("overflow-hidden", {
	variants: {
		variant: {
			box: "border-stroke border shadow-2xs rounded-lg last:mb-0",
			table: "border-b first:rounded-t-xl last:rounded-b-xl last:border-b-0",
			open: "border-b first:rounded-t-xl last:rounded-b-xl last:border-b-0",
		},
		size: {
			sm: "",
			lg: "",
		},
	},
	compoundVariants: [
		{
			variant: "box",
			size: "sm",
			class: "mb-1.5",
		},
		{
			variant: "box",
			size: "lg",
			class: "mb-2",
		},
	],
	defaultVariants: {
		variant: "box",
		size: "sm",
	},
})

const accordionTriggerVariants = cva("bg-bg text-fg outline-hidden flex flex-1 cursor-pointer items-center justify-between text-left font-medium transition-all", {
	variants: {
		variant: {
			box: "",
			table: "",
			open: "",
		},
		size: {
			sm: "",
			lg: "",
		},
		indicator: {
			chevron: "[&[data-state=open]>.AccordionChevron]:rotate-180",
			"plus-minus":
				"[&[data-state=open]>.AccordionPlus>path:last-child]:rotate-90 [&[data-state=open]>.AccordionPlus>path:last-child]:opacity-0 [&[data-state=open]>.AccordionPlus]:rotate-180",
		},
	},
	compoundVariants: [
		{
			variant: "open",
			size: "sm",
			class: "px-0 py-3 leading-5",
		},
		{
			variant: "open",
			size: "lg",
			class: "px-0 py-4 leading-6",
		},
		{
			variant: ["box", "table"],
			size: "sm",
			class: "px-4 py-3 leading-5",
		},
		{
			variant: ["box", "table"],
			size: "lg",
			class: "p-4 leading-6",
		},
		// Indicator sizing
		{
			indicator: ["chevron", "plus-minus"],
			size: "sm",
			class: "[&>.AccordionChevron]:size-5 [&>.AccordionPlus]:size-5",
		},
		{
			indicator: ["chevron", "plus-minus"],
			size: "lg",
			class: "[&>.AccordionChevron]:size-6 [&>.AccordionPlus]:size-6",
		},
	],
	defaultVariants: {
		variant: "box",
		size: "sm",
		indicator: "chevron",
	},
})

const accordionContentVariants = cva("text-fg-secondary data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden transition-all")

const accordionContentInnerVariants = cva("pt-0", {
	variants: {
		variant: {
			box: "",
			table: "",
			open: "",
		},
		size: {
			sm: "",
			lg: "",
		},
	},
	compoundVariants: [
		{
			variant: "open",
			size: "sm",
			class: "px-0 pb-3 pt-0",
		},
		{
			variant: "open",
			size: "lg",
			class: "px-0 pb-4 pt-0",
		},
		{
			variant: ["box", "table"],
			size: "sm",
			class: "px-4 pb-3 pt-0",
		},
		{
			variant: ["box", "table"],
			size: "lg",
			class: "px-4 py-4 pt-0",
		},
	],
	defaultVariants: {
		variant: "box",
		size: "sm",
	},
})

// Defining the hook for the accordion
function useAccordion() {
	const context = React.useContext(AccordionContext)
	if (!context) {
		throw new Error("useAccordion must be used within a <Accordion />")
	}
	return context
}

/* Define the components */
function Accordion({ size = "sm", variant = "box", indicator = "chevron", className, children, ...props }: AccordionProps) {
	return (
		<AccordionContext.Provider value={{ size: size ?? "sm", variant: variant ?? "box", indicator: indicator ?? "chevron" }}>
			<AccordionPrimitive.Root data-slot="accordion" className={classNames(accordionVariants({ size, variant }), className)} {...props}>
				{children}
			</AccordionPrimitive.Root>
		</AccordionContext.Provider>
	)
}
Accordion.displayName = "Accordion"

function AccordionItem({ children, className, ...props }: AccordionItemProps) {
	const { variant, size } = useAccordion()

	return (
		<AccordionPrimitive.Item data-slot="accordion-item" className={classNames(accordionItemVariants({ variant, size }), className)} {...props}>
			{children}
		</AccordionPrimitive.Item>
	)
}

AccordionItem.displayName = "AccordionItem"

function AccordionTrigger({ children, className, ...props }: AccordionTriggerProps) {
	const { size, variant, indicator } = useAccordion()

	return (
		<AccordionPrimitive.Header className="flex">
			<AccordionPrimitive.Trigger data-slot="accordion-trigger" className={classNames(accordionTriggerVariants({ variant, size, indicator }), className)} {...props}>
				{children}
				{indicator === "chevron" && <ChevronDownIcon className="AccordionChevron text-fg-tertiary shrink-0 transition-transform duration-200" aria-hidden />}
				{indicator === "plus-minus" && <Plus className="AccordionPlus text-fg-tertiary shrink-0 transition-transform duration-200" aria-hidden />}
			</AccordionPrimitive.Trigger>
		</AccordionPrimitive.Header>
	)
}

AccordionTrigger.displayName = "AccordionTrigger"

function AccordionContent({ children, className, ...props }: AccordionContentProps) {
	const { size, variant } = useAccordion()

	return (
		<AccordionPrimitive.Content data-slot="accordion-content" className={classNames(accordionContentVariants(), className)} {...props}>
			<div className={classNames(accordionContentInnerVariants({ variant, size }))}>{children}</div>
		</AccordionPrimitive.Content>
	)
}

AccordionContent.displayName = "AccordionContent"

/* Export all components*/
export { Accordion, AccordionContent, AccordionItem, AccordionTrigger }

"use client"

import * as React from "react"
import { VariantProps, cva } from "class-variance-authority"
import { AlertDialog as AlertDialogPrimitive } from "radix-ui"
import { cn } from "@/lib/utils"

type Backdrop = VariantProps<typeof alertDialogOverlayVariants>["backdrop"]
type AlertDialogProps = React.ComponentProps<typeof AlertDialogPrimitive.Root>
type AlertDialogTriggerProps = React.ComponentProps<typeof AlertDialogPrimitive.Trigger>
type AlertDialogPortalProps = React.ComponentProps<typeof AlertDialogPrimitive.Portal>
type AlertDialogOverlayProps = React.ComponentProps<typeof AlertDialogPrimitive.Overlay> & { backdrop?: Backdrop }
type AlertDialogContentProps = React.ComponentProps<typeof AlertDialogPrimitive.Content> & { backdrop?: Backdrop }
type AlertDialogHeaderProps = React.HTMLAttributes<HTMLDivElement>
type AlertDialogFooterProps = React.HTMLAttributes<HTMLDivElement>
type AlertDialogTitleProps = React.ComponentProps<typeof AlertDialogPrimitive.Title>
type AlertDialogDescriptionProps = React.ComponentProps<typeof AlertDialogPrimitive.Description>
type AlertDialogActionProps = React.ComponentProps<typeof AlertDialogPrimitive.Action>
type AlertDialogCancelProps = React.ComponentProps<typeof AlertDialogPrimitive.Cancel>

const alertDialogOverlayVariants = cva(
	"data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50",
	{
		variants: {
			backdrop: {
				overlay: "bg-black/50",
				blur: "backdrop-blur-sm",
				transparent: "bg-transparent",
			},
		},
		defaultVariants: {
			backdrop: "overlay",
		},
	}
)

function AlertDialog({ ...props }: AlertDialogProps) {
	return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
}
AlertDialog.displayName = AlertDialogPrimitive.Root.displayName

function AlertDialogTrigger({ ...props }: AlertDialogTriggerProps) {
	return <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
}
AlertDialogTrigger.displayName = AlertDialogPrimitive.Trigger.displayName

function AlertDialogPortal({ ...props }: AlertDialogPortalProps) {
	return <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
}
AlertDialogPortal.displayName = AlertDialogPrimitive.Portal.displayName

function AlertDialogOverlay({ className, backdrop = "overlay", ...props }: AlertDialogOverlayProps) {
	return <AlertDialogPrimitive.Overlay data-slot="alert-dialog-overlay" className={cn(alertDialogOverlayVariants({ backdrop }), className)} {...props} />
}
AlertDialogOverlay.displayName = AlertDialogPrimitive.Overlay.displayName

function AlertDialogContent({ className, backdrop, ...props }: AlertDialogContentProps) {
	return (
		<AlertDialogPortal>
			<AlertDialogOverlay backdrop={backdrop} />
			<AlertDialogPrimitive.Content
				data-slot="alert-dialog-content"
				className={cn(
					"bg-bg data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 border-alpha fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border p-5 shadow-lg shadow-black/5 duration-200 sm:rounded-lg",
					className
				)}
				{...props}
			/>
		</AlertDialogPortal>
	)
}
AlertDialogContent.displayName = AlertDialogPrimitive.Content.displayName

function AlertDialogHeader({ className, ...props }: AlertDialogHeaderProps) {
	return <div data-slot="alert-dialog-header" className={cn("flex flex-col space-y-1 text-center sm:text-left", className)} {...props} />
}
AlertDialogHeader.displayName = "AlertDialogHeader"

function AlertDialogFooter({ className, ...props }: AlertDialogFooterProps) {
	return <div data-slot="alert-dialog-footer" className={cn("flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2.5", className)} {...props} />
}
AlertDialogFooter.displayName = "AlertDialogFooter"

function AlertDialogTitle({ className, ...props }: AlertDialogTitleProps) {
	return <AlertDialogPrimitive.Title data-slot="alert-dialog-title" className={cn("text-lg font-semibold", className)} {...props} />
}
AlertDialogTitle.displayName = AlertDialogPrimitive.Title.displayName

function AlertDialogDescription({ className, ...props }: AlertDialogDescriptionProps) {
	return <AlertDialogPrimitive.Description data-slot="alert-dialog-description" className={cn("text-fg-secondary text-sm", className)} {...props} />
}
AlertDialogDescription.displayName = AlertDialogPrimitive.Description.displayName

function AlertDialogAction({ ...props }: AlertDialogActionProps) {
	return <AlertDialogPrimitive.Action data-slot="alert-dialog-action" {...props} />
}
AlertDialogAction.displayName = AlertDialogPrimitive.Action.displayName

function AlertDialogCancel({ ...props }: AlertDialogCancelProps) {
	return <AlertDialogPrimitive.Cancel data-slot="alert-dialog-cancel" {...props} />
}
AlertDialogCancel.displayName = AlertDialogPrimitive.Cancel.displayName

export {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogOverlay,
	AlertDialogPortal,
	AlertDialogTitle,
	AlertDialogTrigger,
}

"use client"

import * as React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

type AlertProps = Omit<React.HTMLAttributes<HTMLDivElement>, "color" | "variant"> & VariantProps<typeof alertVariants>
// Variants
const alertVariants = cva("w-full rounded-xl p-3 flex items-center justify-center gap-2", {
	variants: {
		color: {
			neutral: "",
			primary: "",
			info: "",
			success: "",
			error: "",
			warning: "",
		},
		variant: {
			strong: "",
			soft: "",
			"soft-outline": "ring-1 ring-inset",
			outline: "ring-1 ring-inset ring-border bg-transparent",
		},
	},
	compoundVariants: [
		// Soft
		{ color: "neutral", variant: "soft", className: "bg-fill2" },
		{ color: "primary", variant: "soft", className: "bg-primary-accent text-primary-text" },
		{ color: "info", variant: "soft", className: "bg-info-accent text-info-text" },
		{ color: "success", variant: "soft", className: "bg-success-accent text-success-text" },
		{ color: "error", variant: "soft", className: "bg-error-accent text-error-text" },
		{ color: "warning", variant: "soft", className: "bg-warning-accent text-warning-text" },

		// Strong
		{ color: "neutral", variant: "strong", className: "bg-black-inverse text-white-inverse" },
		{ color: "primary", variant: "strong", className: "bg-primary text-white" },
		{ color: "info", variant: "strong", className: "bg-info text-white" },
		{ color: "warning", variant: "strong", className: "bg-warning text-white" },
		{ color: "error", variant: "strong", className: "bg-error text-white" },
		{ color: "success", variant: "strong", className: "bg-success text-white" },

		// Soft-outline
		{ color: "neutral", variant: "soft-outline", className: "outline-border bg-fill2" },
		{ color: "primary", variant: "soft-outline", className: "bg-primary-accent text-primary-text outline-primary-accent" },
		{ color: "info", variant: "soft-outline", className: "bg-info-accent text-info-text outline-info-accent" },
		{ color: "success", variant: "soft-outline", className: "bg-success-accent text-success-text outline-success-accent" },
		{ color: "error", variant: "soft-outline", className: "bg-error-accent text-error-text outline-error-accent" },
		{ color: "warning", variant: "soft-outline", className: "bg-warning-accent text-warning-text outline-warning-accent" },

		// Outline
		{ color: "neutral", variant: "outline", className: "ring-border bg-transparent text-foreground" },
		{ color: "primary", variant: "outline", className: "ring-primary bg-transparent text-primary" },
		{ color: "info", variant: "outline", className: "ring-info bg-transparent text-info" },
		{ color: "success", variant: "outline", className: "ring-success bg-transparent text-success" },
		{ color: "error", variant: "outline", className: "ring-error bg-transparent text-error" },
		{ color: "warning", variant: "outline", className: "ring-warning bg-transparent text-warning" },
	],
	defaultVariants: {
		color: "primary",
		variant: "soft",
	},
})

function Alert({ className, color, variant, ...props }: AlertProps) {
	return <div role="alert" className={cn(alertVariants({ color, variant }), className)} {...props} />
}
Alert.displayName = "Alert"

function AlertTitle({ className, ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
	return <h5 className={cn("text-sm font-medium", className)} {...props} />
}
AlertTitle.displayName = "AlertTitle"

function AlertDescription({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
	return <div className={cn("text-sm", className)} {...props} />
}
AlertDescription.displayName = "AlertDescription"

function AlertContent({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
	return <div className={cn("flex flex-grow flex-col gap-1", className)} {...props} />
}
AlertContent.displayName = "AlertContent"

function AlertIcon({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
	return <div className={cn("flex-shrink-0", className)} {...props} />
}
AlertIcon.displayName = "AlertIcon"

function AlertActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
	return <div className={cn("flex-shrink-0", className)} {...props} />
}
AlertActions.displayName = "AlertActions"

export { Alert, AlertContent, AlertDescription, AlertIcon, AlertTitle, AlertActions, alertVariants }
export type { AlertProps }

"use client"

import React, { createContext, useContext } from "react"
import * as AvatarPrimitive from "@radix-ui/react-avatar"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

type AvatarProps = React.ComponentProps<typeof AvatarPrimitive.Root> & {
	size?: NonNullable<VariantProps<typeof avatarVariants>["size"]>
	rounded?: NonNullable<VariantProps<typeof avatarVariants>["rounded"]>
}
type AvatarImageProps = React.ComponentProps<typeof AvatarPrimitive.Image>
type AvatarFallbackProps = React.ComponentProps<typeof AvatarPrimitive.Fallback>
type AvatarIndicatorProps = React.HTMLAttributes<HTMLDivElement>
type AvatarStatusProps = React.HTMLAttributes<HTMLDivElement> & VariantProps<typeof avatarStatusVariants>

type AvatarContextValue = {
	size: NonNullable<VariantProps<typeof avatarVariants>["size"]>
}

const AvatarContext = createContext<AvatarContextValue | null>(null)

function useAvatarContext() {
	const context = useContext(AvatarContext)
	if (!context) {
		throw new Error("Avatar components must be used within an Avatar")
	}
	return context
}

const avatarVariants = cva("flex items-center font-semibold justify-center shrink-0 relative", {
	variants: {
		size: {
			"16": "size-4 text-xs",
			"20": "size-5 text-xs",
			"24": "size-6 text-xs",
			"32": "size-8 text-sm",
			"36": "size-9 text-sm",
			"40": "size-10 text-sm",
			"48": "size-12 text-base",
			"64": "size-16 text-xl",
			"80": "size-20 text-2xl",
		},
		rounded: {
			circle: "rounded-full",
			square: "",
		},
	},
	compoundVariants: [
		{ size: "16", rounded: "square", class: "rounded-sm" },
		{ size: "20", rounded: "square", class: "rounded-sm" },
		{ size: "24", rounded: "square", class: "rounded-md" },
		{ size: "32", rounded: "square", class: "rounded-md" },
		{ size: "36", rounded: "square", class: "rounded-lg" },
		{ size: "40", rounded: "square", class: "rounded-lg" },
		{ size: "48", rounded: "square", class: "rounded-[10px]" },
		{ size: "64", rounded: "square", class: "rounded-xl" },
		{ size: "80", rounded: "square", class: "rounded-2xl" },
	],
	defaultVariants: {
		size: "40",
		rounded: "circle",
	},
})

const avatarStatusVariants = cva("absolute z-10 border-bg rounded-full box-content", {
	variants: {
		variant: {
			online: "bg-success",
			offline: "bg-fg-disabled",
			busy: "bg-warning",
			away: "bg-info",
		},
		size: {
			"16": "size-1 border",
			"20": "size-1 border",
			"24": "size-1.5 border-2",
			"32": "size-1.5 border-2",
			"36": "size-1.5 border-2",
			"40": "size-2 border-2",
			"48": "size-3 border-2",
			"64": "size-3 border-2",
			"80": "size-4 border-2",
		},
	},
	defaultVariants: {
		variant: "online",
		size: "40",
	},
})

function Avatar({ className, size = "40", rounded = "circle", ...props }: AvatarProps) {
	return (
		<AvatarContext.Provider value={{ size }}>
			<AvatarPrimitive.Root data-slot="avatar" className={cn(avatarVariants({ size, rounded }), className)} {...props} />
		</AvatarContext.Provider>
	)
}
Avatar.displayName = "Avatar"

function AvatarImage({ className, ...props }: AvatarImageProps) {
	return <AvatarPrimitive.Image data-slot="avatar-image" className={cn("relative aspect-square size-full rounded-[inherit] object-cover", className)} {...props} />
}
AvatarImage.displayName = "AvatarImage"

function AvatarFallback({ className, ...props }: AvatarFallbackProps) {
	return (
		<AvatarPrimitive.Fallback
			data-slot="avatar-fallback"
			className={cn("bg-primary-focus text-primary-text flex size-full items-center justify-center rounded-[inherit]", className)}
			{...props}
		/>
	)
}
AvatarFallback.displayName = "AvatarFallback"

function AvatarIndicator({ className, ...props }: AvatarIndicatorProps) {
	return <div data-slot="avatar-indicator" className={cn("absolute z-10 box-content flex items-center justify-center", className)} {...props} />
}
AvatarIndicator.displayName = "AvatarIndicator"

function AvatarStatus({ className, variant, size, ...props }: AvatarStatusProps) {
	const { size: contextSize } = useAvatarContext()
	const statusSize = size || contextSize
	return <div data-slot="avatar-status" className={cn(avatarStatusVariants({ variant, size: statusSize }), className)} {...props} />
}
AvatarStatus.displayName = "AvatarStatus"

export { Avatar, AvatarImage, AvatarFallback, AvatarIndicator, AvatarStatus, avatarStatusVariants, avatarVariants }

"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { type VariantProps, cva } from "class-variance-authority"
import { cn } from "@/lib/utils"

export type BadgeProps = Omit<React.HTMLAttributes<HTMLDivElement>, "color"> &
	VariantProps<typeof badgeVariants> & {
		asChild?: boolean
	}

const badgeVariants = cva("inline-flex items-center font-medium w-fit whitespace-nowrap transition duration-200 gap-1", {
	variants: {
		variant: {
			default: "border border-soft-alpha text-fg-secondary bg-elevation-level1",
			strong: "",
			outline: "",
			soft: "",
		},
		size: {
			"20": "h-5 px-1.5 text-xs rounded-md",
			"24": "h-6 px-2 text-xs rounded-md",
			"28": "h-7 px-2 text-sm rounded-md",
		},
		color: {
			primary: "",
			info: "",
			success: "",
			error: "",
			warning: "",
			neutral: "bg-elevation-level1 border-alpha",
		},
	},
	defaultVariants: {
		variant: "soft",
		size: "24",
		color: "primary",
	},
	compoundVariants: [
		// strong
		{ variant: "strong", color: "primary", className: "bg-primary text-white font-semibold" },
		{ variant: "strong", color: "info", className: "bg-info text-white font-semibold" },
		{ variant: "strong", color: "success", className: "bg-success text-white font-semibold" },
		{ variant: "strong", color: "error", className: "bg-error text-white font-semibold" },
		{ variant: "strong", color: "warning", className: "bg-warning text-white font-semibold" },
		{
			variant: "strong",
			color: "neutral",
			className: "bg-black-inverse border border-alpha text-white-inverse font-medium",
		},

		// outline
		{ variant: "outline", color: "primary", className: "text-primary-text border border-primary bg-transparent" },
		{ variant: "outline", color: "info", className: "text-info-text border border-info bg-transparent" },
		{ variant: "outline", color: "success", className: "text-success-text border border-success bg-transparent" },
		{ variant: "outline", color: "error", className: "text-error-text border border-error bg-transparent" },
		{ variant: "outline", color: "warning", className: "text-warning-text border border-warning bg-transparent" },
		{ variant: "outline", color: "neutral", className: "text-fg-secondary border bg-transparent" },

		// soft
