export { Password }

import React, { useCallback, useEffect, useId, useMemo, useRef, useState } from "react"
import { PhoneIcon } from "lucide-react"
import * as RPNInput from "react-phone-number-input"
import { type Value, getCountries, getCountryCallingCode, isValidPhoneNumber } from "react-phone-number-input"
import flags from "react-phone-number-input/flags"
import { cn } from "@/lib/utils"
import { Button } from "./button"
import { Input } from "./input"
import { Label } from "./label"
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from "./select"

type PhoneNumberPrimitiveProps = Omit<RPNInput.Props<typeof Input>, "inputComponent" | "displayName"> & {
	// size?: InputProps["size"]
	showTrigger?: boolean
	countryDropdown?: boolean
	className?: string
	country?: RPNInput.Country
	onlyCountries?: string[]
	preferredCountries?: string[]
	excludeCountries?: string[]
	label?: string
	hint?: string
	hasError?: boolean
	lead?: React.ReactNode
	trail?: React.ReactNode
	validateOnChange?: boolean
	showValidationIcon?: boolean
	onValidationChange?: (isValid: boolean) => void
	// New prop for controlling auto-selection behavior
	autoSelectFirstCountry?: boolean
}

const PhoneNumber: React.FC<PhoneNumberPrimitiveProps> = ({
	value,
	onChange,
	country,
	onCountryChange,
	// size = "36",
	showTrigger = true,
	countryDropdown = true,
	disabled = false,
	onlyCountries,
	preferredCountries,
	excludeCountries,
	label,
	hint,
	hasError = false,
	international = false,
	countryCallingCodeEditable = international,
	validateOnChange = false,
	// showValidationIcon = false,
	onValidationChange,
	autoSelectFirstCountry = false, // Conservative default
	...rpnInputProps
}) => {
	const id = useId()
	const allCountries = useMemo(() => getCountries(), [])
	const [isValid, setIsValid] = useState<boolean | null>(null)
	const [selectOpen, setSelectOpen] = useState(false)
	const [lastManuallySelectedCountry, setLastManuallySelectedCountry] = useState<RPNInput.Country | null>(null)
	const validationTimeoutRef = useRef<NodeJS.Timeout | null>(null)

	// When international is false, force countryCallingCodeEditable to be false
	const effectiveCountryCallingCodeEditable = international ? countryCallingCodeEditable : false

	// Normalize "US" or "United States" → "US"
	const normalizeCountryIdentifier = useCallback(
		(identifier: string): RPNInput.Country | null => {
			if (allCountries.includes(identifier as RPNInput.Country)) {
				return identifier as RPNInput.Country
			}
			const found = allCountries.find((c) => {
				const regionName = new Intl.DisplayNames(["en"], { type: "region" }).of(c)
				return regionName?.toLowerCase() === identifier.toLowerCase()
			})
			return found || null
		},
		[allCountries]
	)

	// Function to get alternative/common names for countries
	const getAlternativeCountryNames = useCallback((countryCode: string): string[] => {
		const alternatives: Record<string, string[]> = {
			US: ["USA", "United States", "America"],
			GB: ["UK", "United Kingdom", "Britain", "England"],
			DE: ["Germany", "Deutschland"],
			FR: ["France"],
			IT: ["Italy"],
			ES: ["Spain", "España"],
			CN: ["China", "People's Republic of China"],
			JP: ["Japan"],
			KR: ["Korea", "South Korea"],
			RU: ["Russia", "Russian Federation"],
			IN: ["India"],
			BR: ["Brazil"],
			CA: ["Canada"],
			AU: ["Australia"],
			MX: ["Mexico"],
			NL: ["Netherlands", "Holland"],
			BE: ["Belgium"],
			CH: ["Switzerland"],
			AT: ["Austria"],
			SE: ["Sweden"],
			NO: ["Norway"],
			DK: ["Denmark"],
			FI: ["Finland"],
			PT: ["Portugal"],
			GR: ["Greece"],
			TR: ["Turkey"],
			PL: ["Poland"],
			CZ: ["Czech Republic", "Czechia"],
			HU: ["Hungary"],
			RO: ["Romania"],
			BG: ["Bulgaria"],
			HR: ["Croatia"],
			SI: ["Slovenia"],
			SK: ["Slovakia"],
			LT: ["Lithuania"],
			LV: ["Latvia"],
			EE: ["Estonia"],
		}
		return alternatives[countryCode] || []
	}, [])

	// Filter out based on only/exclude lists
	const countries = useMemo(() => {
		let filtered = [...allCountries]
		if (excludeCountries && excludeCountries.length > 0) {
			const excludeCodes = excludeCountries.map(normalizeCountryIdentifier).filter(Boolean) as RPNInput.Country[]
			filtered = filtered.filter((c) => !excludeCodes.includes(c))
		}
		if (onlyCountries && onlyCountries.length > 0) {
			const onlyCodes = onlyCountries.map(normalizeCountryIdentifier).filter(Boolean) as RPNInput.Country[]
			filtered = filtered.filter((c) => onlyCodes.includes(c))
		}
		return filtered
	}, [allCountries, onlyCountries, excludeCountries, normalizeCountryIdentifier])

	// Enhanced country data with search metadata
	const countriesWithSearchData = useMemo(() => {
		return countries.map((c) => {
			const regionName = new Intl.DisplayNames(["en"], { type: "region" }).of(c) || c
			const callingCode = getCountryCallingCode(c)

			// Create search keywords for each country
			const searchKeywords = [
				regionName.toLowerCase(),
				c.toLowerCase(),
				callingCode,
				`+${callingCode}`,
				// Add common alternative names
				...(getAlternativeCountryNames(c) || []).map((name) => name.toLowerCase()),
			]

			return {
				code: c,
				name: regionName,
				callingCode,
				searchKeywords,
			}
		})
	}, [countries, getAlternativeCountryNames])

	// Separate preferred vs. regular with search data
	const { preferredCountriesList, regularCountriesList } = useMemo(() => {
		if (!preferredCountries || preferredCountries.length === 0) {
			return { preferredCountriesList: [], regularCountriesList: countriesWithSearchData }
		}
		const preferredCodes = preferredCountries.map(normalizeCountryIdentifier).filter(Boolean) as RPNInput.Country[]
		const preferred = countriesWithSearchData.filter((c) => preferredCodes.includes(c.code))
		const regular = countriesWithSearchData.filter((c) => !preferredCodes.includes(c.code))
		return { preferredCountriesList: preferred, regularCountriesList: regular }
	}, [countriesWithSearchData, preferredCountries, normalizeCountryIdentifier])

	// Precompute calling codes for performance
	const countryCodeMap = useMemo(() => {
		const m = new Map<RPNInput.Country, string>()
		countries.forEach((c) => {
			m.set(c, getCountryCallingCode(c))
		})
		return m
	}, [countries])

	// Priority for shared calling codes
	const countryPriority = useMemo(
		() =>
			({
				"1": ["US", "CA"],
				"7": ["RU", "KZ"],
				"47": ["NO", "SJ"],
				"590": ["GP", "BL", "MF"],
				"599": ["CW", "BQ"],
				"1242": ["BS"],
				"1246": ["BB"],
				"1264": ["AI"],
				"1268": ["AG"],
			}) as Record<string, string[]>,
		[]
	)

	// Helper: detect country from raw "digits" (without "+") - uses ALL countries for detection
	const detectCountryFromNumber = useCallback(
		(numberWithoutPlus: string): RPNInput.Country | null => {
			// Use ALL countries for detection, not just filtered ones
			const sorted = [...allCountries].sort((a, b) => {
				return getCountryCallingCode(b).length - getCountryCallingCode(a).length
			})

			const matches = sorted.filter((c) => numberWithoutPlus.startsWith(getCountryCallingCode(c)))
			if (matches.length === 0) return null

			let selected = matches[0]
			const firstMatchCode = getCountryCallingCode(matches[0])

			// Check if we have a manually selected country that shares the same calling code
			if (lastManuallySelectedCountry) {
				const manuallySelectedCode = getCountryCallingCode(lastManuallySelectedCountry)
				if (manuallySelectedCode === firstMatchCode && matches.includes(lastManuallySelectedCountry)) {
					// Keep the manually selected country if it has the same calling code
					selected = lastManuallySelectedCountry
				}
			}

			// If no manual selection or different calling code, use priority
			const prioList = countryPriority[firstMatchCode]
			if (prioList) {
				const prioCountry = prioList.find((p) => matches.includes(p as RPNInput.Country))
				if (prioCountry) {
					selected = prioCountry as RPNInput.Country
				}
			}

			// CRITICAL: Only return the detected country if it's in our allowed countries list
			return countries.includes(selected) ? selected : null
		},
		[allCountries, countries, countryPriority, lastManuallySelectedCountry]
	)

	// Smart country management - only applies when autoSelectFirstCountry is true
	const effectiveCountry = useMemo(() => {
		if (autoSelectFirstCountry) {
			// Aggressive mode: auto-select and override
			if (!country && countries.length > 0) {
				return countries[0]
			}
			if (country && !countries.includes(country)) {
				return countries.length > 0 ? countries[0] : undefined
			}
		}
		return country
	}, [country, countries, autoSelectFirstCountry])

	// Conservative display country - only affects UI display, not actual state
	const getDisplayCountry = useCallback(() => {
		// If we have a valid country, use it
		if (effectiveCountry && countries.includes(effectiveCountry)) {
			return effectiveCountry
		}

		// If country is invalid/undefined and we have onlyCountries restriction,
		// show the first allowed country for display purposes only (don't change the actual state)
		if (!autoSelectFirstCountry && onlyCountries && onlyCountries.length > 0 && countries.length > 0) {
			return countries[0]
		}

		// Otherwise, keep original behavior
		return effectiveCountry
	}, [effectiveCountry, countries, onlyCountries, autoSelectFirstCountry])

	// Update parent component when effective country changes (only in aggressive mode)
	useEffect(() => {
		if (autoSelectFirstCountry && effectiveCountry !== country && effectiveCountry && onCountryChange) {
			onCountryChange(effectiveCountry)
		}
	}, [effectiveCountry, country, onCountryChange, autoSelectFirstCountry])

	// Update the lastManuallySelectedCountry when country prop changes from outside
	useEffect(() => {
		if (effectiveCountry) {
			setLastManuallySelectedCountry(effectiveCountry)
		}
	}, [effectiveCountry])

	// Validation logic with debouncing
	const validatePhoneNumber = useCallback(
		(phoneValue: Value | undefined) => {
			if (!validateOnChange || !phoneValue) {
				setIsValid(null)
				onValidationChange?.(false)
				return
			}

			// Clear existing timeout
			if (validationTimeoutRef.current) {
				clearTimeout(validationTimeoutRef.current)
			}

			// Debounce validation by 300ms
			validationTimeoutRef.current = setTimeout(() => {
				try {
					const valid = isValidPhoneNumber(phoneValue)
					setIsValid(valid)
					onValidationChange?.(valid)
				} catch {
					setIsValid(false)
					onValidationChange?.(false)
				}
			}, 300)
		},
		[validateOnChange, onValidationChange]
	)

	// Cleanup timeout on unmount
	useEffect(() => {
		return () => {
			if (validationTimeoutRef.current) {
				clearTimeout(validationTimeoutRef.current)
			}
		}
	}, [])

	const handlePhoneChange = useCallback(
		(val: Value | undefined) => {
			if (disabled) return

			// 🔒 When international is false, completely block "+" and country changes
			if (!international) {
				// Block any input that contains "+"
				if (val && val.includes("+")) {
					// Don't update if trying to add "+"
					return
				}
				// Pass through non-international input
				onChange?.(val)
				validatePhoneNumber(val)
				return
			}

			// 🔒 If country calling code is not editable (but international is true), prevent country changes
			if (!effectiveCountryCallingCodeEditable) {
				// Handle locked mode input restrictions for international mode
				const lockedPrefix = effectiveCountry ? `+${countryCodeMap.get(effectiveCountry)}` : "+"

				if (val === undefined) {
					onChange?.(undefined)
					validatePhoneNumber(undefined)
					return
				}

				if (val === "+") {
					onChange?.("+" as Value)
					validatePhoneNumber("+" as Value)
					return
				}

				if (!val.startsWith(lockedPrefix)) {
					onChange?.(lockedPrefix as Value)
					validatePhoneNumber(lockedPrefix as Value)
					return
				}

				onChange?.(val)
				validatePhoneNumber(val)
				return
			}

			// For international mode with editable country calling codes
			if (effectiveCountryCallingCodeEditable && international && val && val.startsWith("+")) {
				const numberWithoutPlus = val.slice(1)
				const detected = detectCountryFromNumber(numberWithoutPlus)

				// Only change country if detected country is in our allowed list
				if (detected && detected !== effectiveCountry) {
					onCountryChange?.(detected)
				}
				// If detected country is not in allowed list, we simply don't change the country
				// but still allow the phone number input to proceed
			}

			onChange?.(val)
			validatePhoneNumber(val)
		},
		[disabled, international, effectiveCountryCallingCodeEditable, effectiveCountry, countryCodeMap, onChange, validatePhoneNumber, detectCountryFromNumber, onCountryChange]
	)

	// When user selects country from dropdown - allow manual selection even when countryCallingCodeEditable is false
	const handleCountrySelection = useCallback(
		(value: string) => {
			if (disabled) return
			const selectedCode = value as RPNInput.Country
			if (countries.includes(selectedCode)) {
				// Track the manually selected country
				setLastManuallySelectedCountry(selectedCode)
				onCountryChange?.(selectedCode)
			}
		},
		[disabled, countries, onCountryChange]
	)

	// Wrapper for onCountryChange - block automatic country changes that aren't in our allowed list
	const handleCountryChangeWrapper = useCallback(
		(newCountry: RPNInput.Country | undefined) => {
			// Block automatic detection when country calling code is not editable
			if (!effectiveCountryCallingCodeEditable) {
				return
			}

			// Only allow country changes if the new country is in our allowed countries list
			if (newCountry && !countries.includes(newCountry)) {
				// Block the country change if it's not in our allowed list
				return
			}

			onCountryChange?.(newCountry)
		},
		[effectiveCountryCallingCodeEditable, onCountryChange, countries]
	)

	// Custom input component that applies className only to the actual Input
	// const InputWithClass = useMemo(() => {
	// const Comp = (props: InputProps) => {
	// 	// Determine validation trail icon
	// 	let validationTrail = trail
	// 	if (showValidationIcon && isValid !== null) {
	// 		validationTrail = (
	// 			<div className="flex items-center gap-1">
	// 				{isValid ? <span className="text-success text-sm">✓</span> : <span className="text-error text-sm">✗</span>}
	// 				{trail}
	// 			</div>
	// 		)
	// 	}
	// 	// Add onKeyDown handler to prevent "+" when international is false
	// 	const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
	// 		if (!international && (e.key === "+" || e.key === "Plus")) {
	// 			e.preventDefault()
	// 		}
	// 		props.onKeyDown?.(e)
	// 	}
	// 	// Add onPaste handler to filter out "+" when international is false
	// 	const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
	// 		if (!international) {
	// 			const pasteData = e.clipboardData.getData("text")
	// 			if (pasteData.includes("+")) {
	// 				e.preventDefault()
	// 				// Filter out + from pasted content
	// 				const filteredData = pasteData.replace(/\+/g, "")
	// 				if (filteredData) {
	// 					const target = e.target as HTMLInputElement
	// 					const start = target.selectionStart || 0
	// 					const end = target.selectionEnd || 0
	// 					const currentValue = target.value
	// 					const newValue = currentValue.slice(0, start) + filteredData + currentValue.slice(end)
	// 					// Trigger the change event with filtered data
	// 					const syntheticEvent = {
	// 						target: { ...target, value: newValue },
	// 					} as React.ChangeEvent<HTMLInputElement>
	// 					props.onChange?.(syntheticEvent)
	// 				}
	// 			}
	// 		}
	// 		if (!e.defaultPrevented) {
	// 			props.onPaste?.(e)
	// 		}
	// 	}
	// 	return (
	// 		<Input
	// 			{...props}
	// 			data-slot="phone-input"
	// 			aria-label={label || "Phone number"}
	// 			aria-invalid={hasError || (validateOnChange && isValid === false)}
	// 			size={size}
	// 			disabled={disabled}
	// 			start={lead}
	// 			end={validationTrail}
	// 			hasError={hasError || (validateOnChange && isValid === false)}
	// 			className={cn(showTrigger && "rounded-l-none", className, props.className)}
	// 			onKeyDown={handleKeyDown}
	// 			onPaste={handlePaste}
	// 		/>
	// 	)
	// }
	// Comp.displayName = "PhoneNumber.InputWithClass"
	// return Comp
	// }, [className, showTrigger, disabled, hasError, lead, trail, label, showValidationIcon, isValid, validateOnChange, international])

	// Enhanced country item renderer with better search support
	const renderCountryItem = useCallback((countryData: { code: RPNInput.Country; name: string; callingCode: string; searchKeywords: string[] }) => {
		const { code, name, callingCode } = countryData

		return (
			<SelectItem key={code} value={code}>
				<Flag country={code} />
				<span>{name}</span>
				<span className="ml-auto">{`+${callingCode}`}</span>
			</SelectItem>
		)
	}, [])

	// Custom handler for open/close - allow dropdown to open regardless of countryCallingCodeEditable
	const handleSelectOpenChange = useCallback((open: boolean) => {
		setSelectOpen(open)
	}, [])

	// Determine effective error state
	const effectiveHasError = hasError || (validateOnChange && isValid === false)
	const effectiveHint = validateOnChange && isValid === false && !hint ? "Please enter a valid phone number" : hint

	return (
		<div className={cn("text-fg-1 flex flex-col items-start gap-1.5 text-sm", { "cursor-not-allowed": disabled })}>
			{label && (
				<Label htmlFor={id} className={cn({ "text-fg-disabled cursor-not-allowed": disabled })}>
					{label}
				</Label>
			)}
			<div className="flex w-full gap-0">
				{showTrigger && countryDropdown && (
					<Select
						open={selectOpen}
						onOpenChange={handleSelectOpenChange}
						value={getDisplayCountry() ? getDisplayCountry() : undefined} // Use display country for UI
						onValueChange={handleCountrySelection}
						disabled={disabled}>
						<SelectTrigger>
							<SelectValue />
						</SelectTrigger>
						<SelectContent>
							{preferredCountriesList.length > 0 && <SelectGroup>{preferredCountriesList.map(renderCountryItem)}</SelectGroup>}
							{regularCountriesList.length > 0 && <SelectGroup>{regularCountriesList.map(renderCountryItem)}</SelectGroup>}
						</SelectContent>
					</Select>
				)}
				{showTrigger && !countryDropdown && (
					<Button
						variant="soft"
						color="neutral"
						disabled={disabled}
						className={cn("disabled:bg-fill2 border-alpha flex flex-shrink-0 cursor-default items-center justify-center gap-1 rounded-r-none border border-r-0 px-2", {
							"border-error": effectiveHasError && !disabled,
						})}>
						<Flag country={getDisplayCountry()} />
						{international && <span className="text-fg-tertiary">{getDisplayCountry() ? `+${countryCodeMap.get(getDisplayCountry()!)}` : null}</span>}
						{/* No chevron icon when dropdown is disabled */}
					</Button>
				)}

				<RPNInput.default
					{...rpnInputProps}
					id={id}
					className="flex-1"
					country={effectiveCountry} // Use effective country for the actual input
					value={value}
					onChange={handlePhoneChange}
					onCountryChange={handleCountryChangeWrapper}
					flagComponent={() => null}
					countrySelectComponent={() => null}
					// inputComponent={InputWithClass}
					placeholder="Enter phone number"
					disabled={disabled}
					countries={countries} // This restricts the library's internal country detection
					international={international}
					withCountryCallingCode={international}
					countryCallingCodeEditable={effectiveCountryCallingCodeEditable}
					// Force domestic format when international is false
					defaultCountry={international ? undefined : effectiveCountry}
					// Add these props to further restrict the library's behavior
					addInternationalOption={false}
					countryOptionsOrder={countries} // Explicitly set the order to our filtered countries
				/>
			</div>
			{(effectiveHasError || effectiveHint) && (
				<Label className={`flex items-start text-xs font-normal ${effectiveHasError ? "text-error" : "text-fg-tertiary"}`}>{effectiveHint}</Label>
			)}
		</div>
	)
}

const Flag = ({ country }: { country?: RPNInput.Country }) => {
	if (!country) return <PhoneIcon className="text-fg-disabled h-5 w-5" />
	const CountryFlag = flags[country]
	return (
		<span className="flex items-center justify-center overflow-hidden rounded-sm [&>svg]:size-5">
			{CountryFlag ? <CountryFlag title={country} /> : <PhoneIcon className="size-5" />}
		</span>
	)
}

PhoneNumber.displayName = "PhoneNumber"

export { PhoneNumber }

"use client"

import * as React from "react"
import * as PopoverPrimitive from "@radix-ui/react-popover"
import { cn } from "@/lib/utils"

type PopoverProps = React.ComponentProps<typeof PopoverPrimitive.Root>

type PopoverContentProps = React.ComponentProps<typeof PopoverPrimitive.Content>

type PopoverTriggerProps = React.ComponentProps<typeof PopoverPrimitive.Trigger>

function Popover({ children, ...props }: PopoverProps) {
	return <PopoverPrimitive.Root {...props}>{children}</PopoverPrimitive.Root>
}
Popover.displayName = PopoverPrimitive.Root.displayName

function PopoverTrigger({ ...props }: PopoverTriggerProps) {
	return <PopoverPrimitive.Trigger {...props} />
}
PopoverTrigger.displayName = PopoverPrimitive.Trigger.displayName

function PopoverContent({ align = "center", side = "bottom", sideOffset = 4, className, children, ...props }: PopoverContentProps) {
	return (
		<PopoverPrimitive.Portal>
			<PopoverPrimitive.Content
				data-slot="popover-content"
				align={align}
				side={side}
				sideOffset={sideOffset}
				className={cn(
					"text-fg bg-elevation-level1 outline-hidden z-50 w-72 rounded-md border p-4 shadow-md",
					"data-[state=open]:animate-in data-[state=closed]:animate-out",
					"data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
					"data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
					"data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
					className
				)}
				{...props}>
				{children}
			</PopoverPrimitive.Content>
		</PopoverPrimitive.Portal>
	)
}
PopoverContent.displayName = PopoverPrimitive.Content.displayName

export { Popover, PopoverContent, PopoverTrigger }

import React from "react"
import * as ProgressPrimitive from "@radix-ui/react-progress"
import { cn } from "@/lib/utils"
import { Label } from "./label"

// Defines the props for the ProgressBar component, extending the props of ProgressPrimitive.Root
type ProgressBarProps = React.ComponentPropsWithRef<typeof ProgressPrimitive.Root> & {
	className?: string
	indicatorClassName?: string
	label?: string
	disabled?: boolean
	hasError?: boolean
	hint?: string
	valueLabel?: boolean
}
// Defines the ProgressBar functional component
function ProgressBar({ value, valueLabel, className, indicatorClassName, hint, hasError, label, disabled, ...props }: ProgressBarProps) {
	return (
		<div className={cn("text-fg-1 flex w-full flex-col items-start gap-1.5 text-sm", { "cursor-not-allowed": disabled }, className)}>
			{(label || valueLabel) && (
				<div className="flex w-full justify-between">
					<Label className={cn({ "text-fg-disabled cursor-not-allowed": disabled })}>{label}</Label>
					{valueLabel && <span>{value}%</span>}
				</div>
			)}

			<ProgressPrimitive.Root className={cn("bg-fill3 translate-z-0 relative h-2 w-full transform overflow-hidden rounded-full", className)} value={value} {...props}>
				<ProgressPrimitive.Indicator
