import React from "react"
import { Time } from "@internationalized/date"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "./select"

export type TimePickerProps = {
	interval?: number
	value?: Time | null
	onValueChange?: (time: Time | null) => void
	is24Hour?: boolean
	minTime?: string
	maxTime?: string
	defaultValue?: Time
}

/**
 * Converts a Dayjs object to a string in "HH:mm" format.
 * @param time - The Dayjs object to format.
 * @returns The formatted time string.
 */
export function serializeTime(time: Time) {
	const hour = String(time.hour).padStart(2, "0")
	const minute = String(time.minute).padStart(2, "0")
	return `${hour}:${minute}`
}

/**
 * Converts a string in "HH:mm" format to a Time object.
 * @param timeString - The time string to parse.
 * @returns A Time object representing the given time.
 */
function deserializeTime(timeString: string) {
	const [hour, minute] = timeString.split(":").map(Number)
	return new Time(hour, minute)
}

function TimePicker({ interval = 15, onValueChange, is24Hour = false, minTime = "00:00", maxTime = "23:59", defaultValue, value = null, ...props }: TimePickerProps) {
	const isControlled = value !== null

	/* Store the time as a serialized string ("HH:mm") to simplify comparisons and render */
	const [internalValue, setInternalValue] = React.useState<string[]>(defaultValue ? [serializeTime(defaultValue)] : [])

	const currentValue = isControlled ? serializeTime(value) : internalValue[0]

	/**
	 * Generates an array of Dayjs objects representing selectable time options.
	 *
	 * The function computes times starting from minTime until maxTime using the provided interval.
	 * We choose this approach to support various ranges and intervals without hardcoding values.
	 *
	 * @returns An array of Dayjs objects for each selectable time.
	 */
	function generateTimeOptions() {
		const times: Time[] = []
		const [minHour, minMinute] = minTime.split(":").map(Number)
		const [maxHour, maxMinute] = maxTime.split(":").map(Number)

		let currentHour = minHour
		let currentMinute = minMinute

		while (currentHour < maxHour || (currentHour === maxHour && currentMinute <= maxMinute)) {
			const time = new Time(currentHour, currentMinute)
			times.push(time)

			currentMinute += interval
			if (currentMinute >= 60) {
				currentHour += Math.floor(currentMinute / 60)
				currentMinute %= 60
			}
		}

		return times
	}

	const timeOptions = generateTimeOptions()
	/**
	 * Handles value changes when a user selects a time.
	 * Updates the internal state and calls the onValueChange callback.
	 * @param value - The selected time as a string.
	 */
	function handleChange(value: string | undefined) {
		if (!value) {
			onValueChange?.(null)
			setInternalValue([])
		} else {
			onValueChange?.(deserializeTime(value))
			setInternalValue([value])
		}
	}
	// Formats a Time object into a human-readable string based on 12-hour or 24-hour format.
	function formatTime(time: Time) {
		let hour = time.hour
		const minute = String(time.minute).padStart(2, "0")
		if (!is24Hour) {
			const period = hour >= 12 ? "pm" : "am"
			hour = hour % 12
			hour = hour === 0 ? 12 : hour // 12 am/pm handling
			return `${String(hour).padStart(2, "0")}:${minute} ${period}`
		} else {
			return `${String(hour).padStart(2, "0")}:${minute}`
		}
	}

	return (
		<Select value={currentValue} onValueChange={handleChange} {...props}>
			<SelectTrigger>
				<SelectValue />
			</SelectTrigger>
			<SelectContent>
				{timeOptions.map((time, index) => {
					const formatted = formatTime(time)
					return (
						<SelectItem key={index} value={serializeTime(time)}>
							{formatted}
						</SelectItem>
					)
				})}
			</SelectContent>
		</Select>
	)
}

export default TimePicker

import React from "react"
import { type VariantProps, cva } from "class-variance-authority"
import { X } from "lucide-react"
import Link from "next/link"
import { Toaster as Sonner, toast } from "sonner"
import { cn } from "@/lib/utils"
import { IconButton } from "./button"

type ButtonType = {
	label: string
	onClick: (id: string | number) => void
	className?: string
	dismiss?: boolean
	href?: string // Add href property for links
}

type ToastProps = {
	title?: string
	icon?: React.ReactNode
	color?: VariantType
	description?: string
	buttons?: ButtonType[]
	duration?: number
	variant?: "outline" | "strong" | "inverse"
	content?: React.ReactNode
	closable?: boolean
	stack?: boolean
	visibleToasts?: number
	placement?: "horizontal" | "vertical"
	customContent?: React.ReactNode
	applyDefaultStyling?: boolean
	// New boolean flag to determine if it's a custom toast
	isCustom?: boolean

	// Custom content specific options
	closeOnClick?: boolean // Whether clicking anywhere on the toast closes it
	showCloseButton?: boolean
}

// Variant styles
const SonnerVariant = cva("group toast rounded-lg flex justify-between text-sm gap-1 p-2.5 ", {
	variants: {
		color: {
			neutral: "",
			primary: "",
			success: "",
			error: "",
			warning: "",
			info: "",
		},
		variant: {
			outline: "bg-elevation-level1 border border-border group-[.toaster]:text-fg-secondary",
			strong: "",
			inverse: " bg-black-inverse group-[.toaster]:text-fg-inverse",
		},
		placement: {
			horizontal: "items-center",
			vertical: "items-start",
		},
	},
	compoundVariants: [
		// Apply color colors only when variant is "strong"
		{
			variant: "strong",
			color: "primary",
			class: "bg-primary text-white",
		},
		{
			variant: "strong",
			color: "neutral",
			class: "bg-black !text-white relative before:absolute before:inset-0 before:!bg-fill4-alpha overflow-hidden before:pointer-events-none",
		},
		{
			variant: "strong",
			color: "success",
			class: "bg-success text-white",
		},
		{
			variant: "strong",
			color: "error",
			class: "bg-error text-white",
		},
		{
			variant: "strong",
			color: "warning",
			class: "bg-warning text-white",
		},
		{
			variant: "strong",
			color: "info",
			class: "bg-info text-white",
		},
	],
	defaultVariants: {
		color: "neutral",
		variant: "outline",
		placement: "vertical",
	},
})

// Define the type for the toast variant
type VariantType = VariantProps<typeof SonnerVariant>["color"]

// Helper function to get icon color class based on variant and color
const getIconColorClass = (variant?: string, color?: string): string => {
	if (variant === "strong") {
		// For strong variant, icons are always white
		if (color === "neutral") {
			return "text-white"
		}
		return "text-white"
	} else if (variant === "outline") {
		// For neutral and inverse variants, use color color
		return color ? `text-${color}` : ""
	} else if (variant === "inverse") {
		const colorHoverColors = {
			primary: "text-primary-hover",
			error: "text-error-hover",
			success: "text-success-hover",
			warning: "text-warning-hover",
			info: "text-info-hover",
		}
		return (color && colorHoverColors[color as keyof typeof colorHoverColors]) || ""
	}
	return "text-black dark:text-white"
}

// Minimal container for custom content
const CustomContentContainer = cva("group toast rounded-lg w-full h-auto", {
	variants: {
		styled: {
			true: "p-3 bg-gray-500 text-white",
			false: "p-0 bg-transparent",
		},
	},
	defaultVariants: {
		styled: false,
	},
})

// Main consolidated toast function
export function showToast({
	title,
	customContent,
	description,
	variant,
	color = "neutral",
	applyDefaultStyling = false,
	closeOnClick = false,
	showCloseButton,
	icon,
	duration,
	placement = "horizontal",
	buttons = [],
	closable = true,
	isCustom = false, // New parameter with default false
}: ToastProps): string | number {
	const toastId = toast.custom(
		(t) => {
			// If isCustom is true OR customContent is provided, render custom toast
			if (isCustom || customContent) {
				const shouldShowCloseButton = showCloseButton !== undefined ? showCloseButton : closable

				return (
					<div
						className={`${CustomContentContainer({ styled: applyDefaultStyling })} ${closeOnClick ? "cursor-pointer" : ""} relative`}
						onClick={closeOnClick ? () => toast.dismiss(toastId) : undefined}>
						{customContent}
						{/* Optional close button for custom content */}
						{shouldShowCloseButton && (
							<IconButton
								onClick={(e) => {
									e.stopPropagation() // Prevent triggering closeOnClick
									toast.dismiss(toastId)
								}}
								className="absolute right-2 top-2 z-10 cursor-pointer rounded-full"
								aria-label="Close toast">
								<X className="size-4" />
							</IconButton>
						)}
					</div>
				)
			}

			// Apply color class to icon if it exists
			const coloredIcon =
				icon && React.isValidElement(icon)
					? React.cloneElement(icon as React.ReactElement<React.HTMLAttributes<HTMLElement>>, {
							...(icon.props || {}),
							className: cn((icon.props && (icon.props as React.HTMLAttributes<HTMLElement>).className) || "", getIconColorClass(variant, color ?? undefined)),
						})
					: icon

			// Default structured toast
			return (
				<div className={SonnerVariant({ color, variant, placement })}>
					{coloredIcon}
					<div
						className={cn("flex", {
							"flex-col items-start gap-1.5": placement === "vertical",
							"flex-row items-center gap-2": placement === "horizontal",
						})}>
						{/* Content */}
						<div className="flex min-w-0 flex-1 flex-col gap-0.5 px-1">
							{title && (
								<div
									className={cn("font-medium", {
										"text-fg": variant === "outline",
										"text-fg-inverse": variant === "inverse",
									})}>
									{title}
								</div>
							)}
							{description && <div className="min-w-47 whitespace-pre-wrap break-words">{description}</div>}
						</div>

						{/* Buttons */}
						{buttons.length > 0 && (
							<div className="flex gap-3 px-1">
								{buttons.map((button, index) => (
									<Link
										href={button.href || ""} // Use the href from button or fallback to empty string
										className="inline-flex h-5 items-center" // Set specific height
										key={index}
										onClick={() => {
											button.onClick(t)
											if (button.dismiss !== false) {
												toast.dismiss(t)
											}
										}}>
										<span
											className={cn("font-inter whitespace-nowrap font-medium tracking-tight underline", {
												"text-fg": variant === "outline",
												"text-fg-inverse": variant === "inverse",
											})}>
											{button.label}
										</span>
									</Link>
								))}
							</div>
						)}
					</div>

					{/* Close button */}
					{closable && (
						<div
							onClick={function () {
								toast.dismiss(toastId)
							}}
							className={`flex cursor-pointer items-center justify-center p-0.5`}>
							<X className="size-4" />
						</div>
					)}
				</div>
			)
		},
		{
			duration,
		}
	)
	return toastId
}

// For structured toasts (backward compatibility)
export function showStructuredToast(options: Omit<ToastProps, "customContent">) {
	return showToast(options)
}

// For completely custom toasts (backward compatibility - now uses isCustom flag)
